// Bencode encoder: converts JS values into their bencoded string form.
// Bencode output is always pure ASCII (markers, digits, and raw byte strings),
// so it is represented as a plain JavaScript string.

import { ByteString } from './types.mjs';

// Encode an integer: i<decimal digits>e
function encodeInt(value) {
  return 'i' + value.toString() + 'e';
}

// Encode a byte string: <length>:<raw bytes>
function encodeBytes(value) {
  return String(value.length) + ':' + value;
}

// Encode a list: l<encoded items>e
function encodeList(values) {
  let out = 'l';
  for (const item of values) {
    out += encode(item);
  }
  return out + 'e';
}

// Encode a dictionary: d<encoded key/value pairs>e (keys sorted)
function encodeDict(entries) {
  const keys = Object.keys(entries).sort();
  let out = 'd';
  for (const key of keys) {
    out += encodeBytes(key) + encode(entries[key]);
  }
  return out + 'e';
}

export function encode(value) {
  if (typeof value === 'number' && Number.isInteger(value)) {
    return encodeInt(value);
  }
  if (typeof value === 'bigint') {
    return encodeInt(value);
  }
  if (typeof value === 'string') {
    return encodeBytes(value);
  }
  if (value instanceof ByteString) {
    return encodeBytes(value.text);
  }
  if (Array.isArray(value)) {
    return encodeList(value);
  }
  if (value !== null && typeof value === 'object') {
    return encodeDict(value);
  }
  throw new TypeError('unsupported type for bencode: ' + typeof value);
}

