// Bencode decoder: parses a bencoded string back into JS values.
// Integers become Numbers, byte strings become ByteString instances,
// lists become Arrays, and dictionaries become plain objects.

import { ByteString } from './types.mjs';

export function decode(data) {
  let pos = 0;

  function parse() {
    if (pos >= data.length) {
      throw new Error('unexpected end of bencode data');
    }
    const ch = data[pos];
    if (ch === 'i') return parseInt_();
    if (ch === 'l') return parseList();
    if (ch === 'd') return parseDict();
    if (ch >= '0' && ch <= '9') return parseBytes();
    throw new Error("invalid bencode token at position " + pos + ": '" + ch + "'");
  }

  function parseInt_() {
    pos += 1; // skip 'i'
    const end = data.indexOf('e', pos);
    if (end === -1) {
      throw new Error('unterminated integer');
    }
    const text = data.slice(pos, end);
    if (!/^-?\d+$/.test(text)) {
      throw new Error('invalid integer: ' + JSON.stringify(text));
    }
    pos = end + 1;
    return Number.parseInt(text, 10);
  }

  function parseBytes() {
    const colon = data.indexOf(':', pos);
    if (colon === -1) {
      throw new Error('malformed byte string length');
    }
    const lengthText = data.slice(pos, colon);
    if (!/^\d+$/.test(lengthText)) {
      throw new Error('invalid byte string length: ' + JSON.stringify(lengthText));
    }
    const length = Number.parseInt(lengthText, 10);
    const start = colon + 1;
    const text = data.slice(start, start + length);
    if (text.length !== length) {
      throw new Error('byte string shorter than declared length');
    }
    pos = start + length;
    return new ByteString(text);
  }

  function parseList() {
    pos += 1; // skip 'l'
    const items = [];
    while (data[pos] !== 'e') {
      if (pos >= data.length) {
        throw new Error('unterminated list');
      }
      items.push(parse());
    }
    pos += 1; // skip 'e'
    return items;
  }

  function parseDict() {
    pos += 1; // skip 'd'
    const entries = {};
    while (data[pos] !== 'e') {
      if (pos >= data.length) {
        throw new Error('unterminated dictionary');
      }
      const key = parseBytes();
      entries[key.text] = parse();
    }
    pos += 1; // skip 'e'
    return entries;
  }

  const value = parse();
  if (pos !== data.length) {
    throw new Error('trailing data after bencode value');
  }
  return value;
}

