// Shared value types for the bencode library.
// ByteString wraps a raw string of bytes so it can be distinguished from
// plain data when decoding (mirrors Python's bytes type).

export class ByteString {
  constructor(text) {
    this.text = text;
  }

  get length() {
    return this.text.length;
  }

  toString() {
    return this.text;
  }
}

