// Python-style formatting helpers so console output matches print() exactly.

import { ByteString } from './bencode/types.mjs';

// Render a string the way Python's repr() renders a bytes object:
// b'...' with non-printable / non-ASCII characters escaped.
export function reprBytes(text) {
  let out = "b'";
  for (let i = 0; i < text.length; i += 1) {
    const code = text.charCodeAt(i);
    const ch = text[i];
    if (ch === "'" || ch === '\\') {
      out += '\\' + ch;
    } else if (code === 9) {
      out += '\\t';
    } else if (code === 10) {
      out += '\\n';
    } else if (code === 13) {
      out += '\\r';
    } else if (code >= 32 && code < 127) {
      out += ch;
    } else {
      out += '\\x' + code.toString(16).padStart(2, '0');
    }
  }
  return out + "'";
}

// Render a string the way Python's repr() renders a str object.
export function reprStr(text) {
  let out = "'";
  for (let i = 0; i < text.length; i += 1) {
    const ch = text[i];
    if (ch === "'" || ch === '\\') {
      out += '\\' + ch;
    } else {
      out += ch;
    }
  }
  return out + "'";
}

// Render any decoded bencode value the way Python's print() would.
export function reprValue(value) {
  if (typeof value === 'number' || typeof value === 'bigint') {
    return value.toString();
  }
  if (typeof value === 'string') {
    return reprStr(value);
  }
  if (value instanceof ByteString) {
    return reprBytes(value.text);
  }
  if (Array.isArray(value)) {
    return '[' + value.map(reprValue).join(', ') + ']';
  }
  if (value !== null && typeof value === 'object') {
    const parts = Object.keys(value).map(
      (key) => reprStr(key) + ': ' + reprValue(value[key]),
    );
    return '{' + parts.join(', ') + '}';
  }
  return String(value);
}

