// Minimal re-implementation of the argparse behaviour this script needs:
// two required integer options --a and --b, plus -h/--help.
// Supports both "--opt value" and "--opt=value" forms, like argparse.

import { basename } from 'node:path';

function usage(prog) {
  return `usage: ${prog} [-h] --a A --b B`;
}

function helpText(prog) {
  return (
    usage(prog) +
    '\n\noptions:\n' +
    '  -h, --help  show this help message and exit\n' +
    '  --a A\n' +
    '  --b B'
  );
}

function fail(prog, message) {
  console.error(usage(prog));
  console.error(`${prog}: error: ${message}`);
  process.exit(2);
}

function parseIntArg(prog, option, raw) {
  const trimmed = String(raw).trim();
  if (!/^[+-]?\d+$/.test(trimmed)) {
    fail(prog, `argument ${option}: invalid int value: '${raw}'`);
  }
  return Number.parseInt(trimmed, 10);
}

export function parseArgs(argv, prog = basename(process.argv[1] || 'test14.mjs')) {
  const values = {};

  for (let i = 0; i < argv.length; i += 1) {
    const token = argv[i];
    let option = token;
    let inlineValue;

    const eq = token.indexOf('=');
    if (token.startsWith('--') && eq !== -1) {
      option = token.slice(0, eq);
      inlineValue = token.slice(eq + 1);
    }

    if (option === '-h' || option === '--help') {
      console.log(helpText(prog));
      process.exit(0);
    }

    if (option === '--a' || option === '--b') {
      let raw = inlineValue;
      if (raw === undefined) {
        i += 1;
        if (i >= argv.length) {
          fail(prog, `argument ${option}: expected one argument`);
        }
        raw = argv[i];
      }
      values[option] = parseIntArg(prog, option, raw);
    } else {
      fail(prog, `unrecognized arguments: ${token}`);
    }
  }

  const missing = [];
  if (values['--a'] === undefined) missing.push('--a');
  if (values['--b'] === undefined) missing.push('--b');
  if (missing.length > 0) {
    fail(prog, `the following arguments are required: ${missing.join(', ')}`);
  }

  return { a: values['--a'], b: values['--b'] };
}

