import { encode, decode } from './lib/bencode/index.mjs';
import { reprBytes, reprValue } from './lib/pyformat.mjs';

const args = parseArgs(process.argv.slice(2));

const numbers = [args.a, args.b, args.a + args.b, args.a * args.b];
const encoded = encode(numbers); // Encode list of numbers
const decoded = decode(encoded); // Decode numbers
const encodedNegative = encode(-args.a); // Encode negative number
const encodedZero = encode(0); // Encode zero
console.log(reprBytes(encoded));
console.log(reprValue(decoded));
console.log(reprBytes(encodedNegative));
console.log(reprBytes(encodedZero));

